effect.shader:
vec4 tex(vec2 p){ return texture2DCv(inputImg.texture, p); }
void main(){
vec2 uv = acScreenNorm;
vec4 src = tex(uv);
vec2 st = 1.0 / max(acScreenSize, vec2(1.0));
float line = floor(uv.y * acScreenSize.y / max(lineHeight, 1.0));
float odd = mod(line, 2.0);
float flick = step(0.5, fract(acTime * speed));
float shift = offset * odd * flick * st.x;
vec2 u2 = clamp(uv + vec2(shift * mixAmt, 0.0), vec2(0.0), vec2(1.0));
vec4 c = tex(u2);
c.rgb *= (1.0 - scanDark * odd);
gl_FragColor = vec4(c.rgb, c.a);
}
